import { isMobileLayout, useAdaptiveLayout } from '@ds/adaptive';
import { BottomSheetCustom, BottomSheetCustomProps, OVERLAY_SURFACE, OverlaySurfaceProvider } from '@ds/bottom-sheet';
import { PopupCloseButton } from '@ds/popup-private';
import { usePortalContext } from '@ds/portal-context';
import {
  extractSupportProps,
  isBrowser,
  useLayoutEffect,
  useModalOpenState,
  useOverlayStack,
  WithSupportProps,
} from '@ds/utils';
import cn from 'classnames';
import { ReactNode, useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { RemoveScroll } from 'react-remove-scroll';

import { MODE, TEST_IDS, WIDTH } from '../../constants';
import {
  DialogBody,
  DialogBodyProps,
  DialogFooter,
  DialogFooterProps,
  DialogHeader,
  DialogHeaderProps,
} from '../../helperComponents';
import { ModalMode, ModalWidth } from '../../types';
import { useModalFocusTrap } from './hooks';
import styles from './styles.module.scss';

type ModalContainer = HTMLElement | string;

export type ModalCustomProps = WithSupportProps<{
  /** Управление состоянием показан/не показан */
  open: boolean;
  /** Колбэк закрытия */
  onClose(): void;
  /**
   * Режим закрытия: Regular — overlay/Esc/кнопка; Aggressive — только кнопка; Forced — без кнопки и overlay/Esc.
   * Aggressive и Forced размывают фон под подложкой.
   * На mobile Aggressive запрещает закрытие кликом по подложке, Forced также отключает свайп.
   * @default MODE.Regular
   */
  mode?: ModalMode;
  /** Содержимое окна (композиция Header/Body/Footer) */
  children: ReactNode;
  /** CSS-класс окна */
  className?: string;
  /** CSS-класс корневого слоя портала */
  rootClassName?: string;
  /** Размер окна */
  width?: ModalWidth;
  /** Растягивать по высоте в пределах контейнера */
  heightAuto?: boolean;
  /** Явный DOM-контейнер для `createPortal`; иначе `usePortalContext()` или `document.body`. */
  container?: ModalContainer;
  /** Закрытие при навигации по истории */
  closeOnPopstate?: boolean;
  /**
   * Блокировать прокрутку вне модального окна. `false` позволяет передать управление внешнему оверлею.
   * @default true
   */
  lockScroll?: boolean;
}> &
  // Только mobile: управляют sheet-поверхностью (на desktop игнорируются).
  Pick<BottomSheetCustomProps, 'snapPoints' | 'swipeEnabled' | 'safeAreaTop' | 'safeAreaBottom' | 'showBackdrop'>;

/** Desktop-frame модалки: портал + overlay + close-button + width/mode/heightAuto. Surface='modal'. */
function ModalFrame({
  open = false,
  onClose,
  mode = MODE.Regular,
  children,
  className,
  rootClassName,
  width = WIDTH.S,
  heightAuto = true,
  container,
  closeOnPopstate,
  lockScroll = true,
  ...rest
}: ModalCustomProps) {
  const close = useCallback(() => {
    onClose?.();
  }, [onClose]);

  const isRegular = mode === MODE.Regular;
  const hasCloseButton = mode !== MODE.Forced;
  const overlayBackdropBlur = mode === MODE.Aggressive || mode === MODE.Forced;

  useModalOpenState(
    Boolean(open),
    () => {
      if (hasCloseButton) {
        close();
      }
    },
    { closeOnPopstate, closeByCloseWatcher: false },
  );

  const isTopOverlay = useOverlayStack(open, isRegular ? close : undefined);

  const [portalContainer, setPortalContainer] = useState<HTMLElement | null>(null);
  const portalContextRef = usePortalContext();

  useLayoutEffect(() => {
    if (!isBrowser()) {
      setPortalContainer(null);
      return;
    }

    if (!open) {
      // При следующем открытии стек сохраняет внешний фокус до монтирования autoFocus-полей.
      setPortalContainer(null);
      return;
    }

    const doc = window.document;

    if (container === undefined) {
      // Ref родительского DOM-узла может заполниться после layout-эффектов дочерней модалки.
      setPortalContainer(portalContextRef.current);
      return;
    }

    if (typeof container === 'string') {
      const nextContainer = doc.querySelector(container);

      setPortalContainer(nextContainer instanceof HTMLElement ? nextContainer : doc.body);
      return;
    }

    setPortalContainer(container);
  }, [open, container, portalContextRef]);

  useEffect(() => {
    if (isBrowser() && open && container === undefined && !portalContainer) {
      setPortalContainer(portalContextRef.current ?? window.document.body);
    }
  }, [open, container, portalContextRef, portalContainer]);

  const focusTrapActive = Boolean(open && portalContainer);
  const dialogRef = useModalFocusTrap(focusTrapActive, isTopOverlay);

  if (!open || !portalContainer) {
    return null;
  }

  return createPortal(
    <RemoveScroll enabled={lockScroll}>
      <div
        className={cn(styles.root, rootClassName)}
        data-overlay-blur={overlayBackdropBlur ? 'true' : undefined}
        data-acrylic-appearance='neutral'
        data-acrylic-level='1Level'
      >
        <div
          className={styles.blackout}
          aria-hidden
          data-test-id={TEST_IDS.overlay}
          onClick={event => {
            event.stopPropagation();

            if (isRegular) {
              close();
            }
          }}
        />

        <div
          className={cn(styles.modal, className)}
          data-width={width}
          data-mode={mode}
          data-height-auto={heightAuto || undefined}
          role='dialog'
          aria-modal='true'
          ref={dialogRef}
          tabIndex={-1}
          {...extractSupportProps(rest)}
        >
          <OverlaySurfaceProvider surface={OVERLAY_SURFACE.Modal}>{children}</OverlaySurfaceProvider>

          {hasCloseButton && (
            <div className={styles.closeButtonWrapper}>
              <PopupCloseButton aria-label='close modal' data-test-id={TEST_IDS.closeButton} onClick={close} />
            </div>
          )}
        </div>
      </div>
    </RemoveScroll>,
    portalContainer,
  );
}

/**
 * Адаптивный low-level `ModalCustom`: на `mobile` — `BottomSheetCustom`, иначе — `ModalFrame`.
 * Композиция одна (surface-aware слоты `.Header/.Body/.Footer`). Форс — `withLayoutType`.
 */
export function ModalCustom(props: ModalCustomProps) {
  const { layoutType } = useAdaptiveLayout();

  if (isMobileLayout(layoutType)) {
    const {
      open = false,
      onClose,
      mode,
      children,
      className,
      rootClassName,
      container,
      closeOnPopstate,
      snapPoints,
      swipeEnabled,
      safeAreaTop,
      safeAreaBottom,
      showBackdrop,
      lockScroll,
      ...rest
    } = props;
    return (
      <BottomSheetCustom
        open={open}
        onClose={onClose}
        mode={mode}
        container={container}
        className={className}
        rootClassName={rootClassName}
        closeOnPopstate={closeOnPopstate}
        snapPoints={snapPoints}
        swipeEnabled={swipeEnabled}
        safeAreaTop={safeAreaTop}
        safeAreaBottom={safeAreaBottom}
        showBackdrop={showBackdrop}
        lockScroll={lockScroll}
        {...extractSupportProps(rest)}
      >
        {children}
      </BottomSheetCustom>
    );
  }

  return <ModalFrame {...props} />;
}

export namespace ModalCustom {
  export type HeaderProps = DialogHeaderProps;
  export type BodyProps = DialogBodyProps;
  export type FooterProps = DialogFooterProps;
  export const Header = DialogHeader;
  export const Body = DialogBody;
  export const Footer = DialogFooter;
}
